files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #0f3460;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 20px;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-align: center;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

input[type="text"] {
  flex: 1;
  padding: 12px;
  font-family: inherit;
  font-size: 1rem;
  background: #0f3460;
  border: 3px solid #533483;
  color: #e0e0e0;
  outline: none;
  min-width: 0;
}

input[type="text"]:focus {
  border-color: #e94560;
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

input::placeholder {
  color: #888;
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 20px;
  background: #e94560;
  color: #fff;
  border: 3px solid #e94560;
  cursor: pointer;
  text-transform: uppercase;
  font-weight: bold;
  letter-spacing: 1px;
  transition: background 0.15s, transform 0.1s;
  white-space: nowrap;
}

button:hover {
  background: #ff6b81;
  border-color: #ff6b81;
}

button:active {
  transform: translate(2px, 2px);
  background: #c73650;
}

button:focus-visible {
  outline: 3px solid #ffd700;
  outline-offset: 2px;
}

.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-size: 1rem;
  color: #a0a0b0;
}

.counts strong {
  color: #ffd700;
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #0f3460;
  padding: 10px 12px;
  border: 2px solid #533483;
}

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
  flex-shrink: 0;
}

.todo-item .text {
  flex: 1;
  word-break: break-word;
}

.todo-item.done .text {
  text-decoration: line-through;
  color: #777;
}

.todo-item .delete-btn {
  padding: 6px 10px;
  font-size: 0.875rem;
  background: transparent;
  border: 2px solid #e94560;
  color: #e94560;
}

.todo-item .delete-btn:hover {
  background: #e94560;
  color: #fff;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 #0f3460;
  }
  h1 {
    font-size: 1.4rem;
  }
  .input-row {
    flex-direction: column;
  }
  button {
    width: 100%;
  }
}

(function () {
  'use strict';

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('todo-add');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');
  var listEl = document.getElementById('todo-list');

  var tasks = [];
  var nextId = 1;

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    var remaining = tasks.filter(function (t) { return !t.done; }).length;
    remainingEl.textContent = String(remaining);
  }

  function addTask() {
    var text = input.value.trim();
    if (text === '') return;

    var id = nextId++;
    var task = { id: id, text: text, done: false };
    tasks.push(task);

    var li = document.createElement('li');
    li.className = 'todo-item';
    li.dataset.id = String(id);

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + id;
    checkbox.setAttribute('aria-label', 'Mark task complete: ' + text);

    var span = document.createElement('span');
    span.className = 'text';
    span.id = 'todo-text-' + id;
    span.textContent = text;

    var delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete-btn';
    delBtn.id = 'todo-delete-' + id;
    delBtn.textContent = 'Delete';
    delBtn.setAttribute('aria-label', 'Delete task: ' + text);

    checkbox.addEventListener('change', function () {
      task.done = checkbox.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    delBtn.addEventListener('click', function () {
      tasks = tasks.filter(function (t) { return t.id !== id; });
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(delBtn);
    listEl.appendChild(li);

    input.value = '';
    input.focus();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);

  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addTask();
    }
  });

  updateCounts();
})();
